  def self.keys
    DEFINITIONS.keys
  end

  def self.[](key)
    DEFINITIONS[key.to_s]
  end

  def self.fetch(key)
    DEFINITIONS.fetch(key.to_s) { DEFINITIONS.fetch(DEFAULT_KEY) }
  end

  def self.valid_key?(key)
    key.present? && DEFINITIONS.key?(key.to_s)
  end
end
